<script setup lang="ts">
import type { FileDto, StreamDto } from '../../api/contracts'; import { fmtSize } from '../../lib/media';
defineProps<{ files: FileDto[] }>();
const types: Record<string, string> = { Video: '视频', Audio: '音频', Subtitle: '字幕' };
function parameters(s: StreamDto) { return (s.Type === 'Video' ? [s.Codec?.toUpperCase(), s.Width && s.Height ? `${s.Width}×${s.Height}` : '', s.BitRate ? `${Math.round(s.BitRate / 1000)} kbps` : '', s.Profile, s.BitDepth ? `${s.BitDepth}bit` : ''] : [s.Codec?.toUpperCase(), s.ChannelLayout || (s.Channels ? `${s.Channels}ch` : ''), s.BitRate ? `${Math.round(s.BitRate / 1000)} kbps` : '', s.Language, s.SampleRate ? `${s.SampleRate} Hz` : '']).filter(Boolean).join(' · ') || '—'; }
</script>
<template><section class="detail-section"><h3>媒体信息 <small>{{ files.length }} 个文件</small></h3><div v-for="file in files" :key="file.index" class="detail-file"><div class="detail-file-head"><strong>{{ file.role === 'main' ? '主文件' : `分段 ${file.index - 1}` }}</strong><span class="mono">{{ file.name }}</span><span class="hint" style="margin:0">{{ fmtSize(file.size) }}</span><span v-if="!file.probed" class="badge pending">未探测</span></div><div v-if="file.streams.length" class="table-wrap"><table><thead><tr><th>#</th><th>类型</th><th>参数</th><th>标记</th></tr></thead><tbody><tr v-for="(s, index) in file.streams" :key="index"><td class="mono">#{{ s.Index ?? '' }}</td><td>{{ types[s.Type || ''] || s.Type || '—' }}</td><td class="mono">{{ parameters(s) }}</td><td class="mono">{{ [s.IsDefault ? '默认' : '', s.IsForced ? '强制' : '', s.IsExternal ? '外挂' : ''].filter(Boolean).join(' ') || '—' }}</td></tr></tbody></table></div><p v-else class="hint" style="margin:8px 0 0">未探测</p><p class="detail-path mono">{{ file.path }}</p></div></section>
</template>
